// Responde GET /api/fornos para o serviço de umidade.
// Os valores vêm das variáveis globais gravadas pelo nó "Escala leitura Modbus".
const agora = Date.now();
const VALIDADE_MS = 30000; // sem atualização há mais de 30 s = leitura inválida

function forno(nome, prefixo) {
    const lidoEm = global.get(prefixo + '_lido_em') || 0;
    const velho = (agora - lidoEm) > VALIDADE_MS;
    return {
        forno: nome,
        velocidade_hz: velho ? null : global.get(prefixo + '_hz'),
        rosca_hz: velho ? null : (global.get(prefixo + '_rosca_hz') ?? null),
        pressao_vapor_bar: velho ? null : global.get(prefixo + '_pressao_bar'),
        rodando: !velho && !!global.get(prefixo + '_rodando'),
        // PT100 na saída do produto: fica null até o sensor ser instalado
        temp_saida_produto_c: velho ? null : (global.get(prefixo + '_temp_saida_c') ?? null),
        lido_em: lidoEm ? new Date(lidoEm).toISOString() : null
    };
}

msg.payload = {
    fornos: [forno('Forno 01', 'forno1'), forno('Forno 02', 'forno2')],
    ts: new Date(agora).toISOString()
};
return msg;

// Ligue aqui a saída do nó modbus-read que lê o M580 (FC3, holding registers).
// AJUSTE os índices e as escalas para o seu mapa de %MW. Exemplo com 4 registradores (%MW100..%MW103):
//   [0] rotação forno 1 em Hz x10   (425 = 42,5 Hz)
//   [1] rotação forno 2 em Hz x10
//   [2] pressão do vapor em bar x10 (manométrica; a mesma caldeira para os dois fornos)
//   [3] status: bit0 = forno 1 girando, bit1 = forno 2 girando
//   [4] rosca dosadora forno 1 em Hz x10 (frequência de saída do inversor)
//   [5] rosca dosadora forno 2 em Hz x10
//   [6] (futuro) PT100 saída produto forno 1 em °C x10
//   [7] (futuro) PT100 saída produto forno 2 em °C x10
const r = msg.payload;
if (!Array.isArray(r) || r.length < 6) { node.warn('Leitura Modbus inesperada'); return null; }
const t = Date.now();

global.set('forno1_hz', r[0] / 10);
global.set('forno2_hz', r[1] / 10);
global.set('forno1_pressao_bar', r[2] / 10);
global.set('forno2_pressao_bar', r[2] / 10);
global.set('forno1_rodando', (r[3] & 1) !== 0);
global.set('forno2_rodando', (r[3] & 2) !== 0);
global.set('forno1_rosca_hz', r[4] / 10);
global.set('forno2_rosca_hz', r[5] / 10);
// PT100: só grava se o registrador existir (sensor instalado)
if (r.length >= 8) {
    global.set('forno1_temp_saida_c', r[6] / 10);
    global.set('forno2_temp_saida_c', r[7] / 10);
}
global.set('forno1_lido_em', t);
global.set('forno2_lido_em', t);

node.status({ fill: 'green', shape: 'dot',
    text: `F1 ${r[0] / 10}/${r[4] / 10} Hz | F2 ${r[1] / 10}/${r[5] / 10} Hz | ${r[2] / 10} bar` });
return null;
